def longest_even_vowels(tape):
    bit = {"a": 1, "e": 2, "i": 4, "o": 8, "u": 16}
    first = {0: -1}
    mask = 0
    best = 0
    for i, ch in enumerate(tape):
        mask ^= bit.get(ch, 0)
        if mask in first:
            best = max(best, i - first[mask])
        else:
            first[mask] = i
    return best

